function labPlayer(turn){return turn===0?game.lesson.settings.teamOne:game.lesson.settings.teamTwo;}
function labClassicResult(d,message){labWin(message||labPlayer(d.turn)+' wins!');}
function labCheckerMoves(d,from=null,jumpsOnly=false){const moves=[];for(let i=0;i<d.board.length;i++){const p=d.board[i];if(!p||p.owner!==d.turn||from!==null&&i!==from)continue;const x=i%d.w,y=Math.floor(i/d.w);for(const dy of p.king?[-1,1]:[d.turn===0?-1:1])for(const dx of [-1,1]){const u=x+dx,v=y+dy;if(u<0||u>=d.w||v<0||v>=d.w)continue;const n=v*d.w+u;if(!d.board[n]&&!jumpsOnly)moves.push({from:i,to:n,capture:null});if(d.board[n]&&d.board[n].owner!==d.turn){const a=x+dx*2,b=y+dy*2;if(a>=0&&a<d.w&&b>=0&&b<d.w&&!d.board[b*d.w+a])moves.push({from:i,to:b*d.w+a,capture:n});}}}const jumps=moves.filter(m=>m.capture!==null);return jumps.length?jumps:jumpsOnly?[]:moves;}
function labLineWinner(d,need){for(let y=0;y<d.h;y++)for(let x=0;x<d.w;x++){const v=d.board[y*d.w+x];if(v<0)continue;for(const [dx,dy] of [[1,0],[0,1],[1,1],[-1,1]])if(Array.from({length:need},(_,k)=>[x+dx*k,y+dy*k]).every(([u,w])=>u>=0&&u<d.w&&w>=0&&w<d.h&&d.board[w*d.w+u]===v))return v;}return -1;}
function labChess(d){const chess=new LabChess();for(const move of d.history)chess.move(move);return chess;}
LAB_ENGINES.classics={
 init(c,seed){const v=c.variant,r=labRand(seed),d={turn:0,selected:null,history:[],quiet:0,promotion:null,side:1,score:[0,0]};
 if(v==='tic'){d.need=3+(seed-1)%4;d.w=d.need+((seed-1)%4>0?1:0);d.h=d.w;d.board=Array(d.w*d.h).fill(-1);}
 if(v==='fourrow'){d.w=7;d.h=6;d.need=4;d.board=Array(42).fill(-1);}
 if(v==='corners'){d.w=5;d.h=5;d.board=Array(25).fill(-1);}
 if(v==='checkers'||v==='kids'){d.w=v==='kids'?6:8;d.h=d.w;d.board=Array.from({length:d.w*d.w},(_,i)=>{const y=Math.floor(i/d.w),x=i%d.w;return (x+y)%2===1&&(y<d.w/2-1||y>d.w/2)?{owner:y<d.w/2?1:0,king:false}:null;});d.forced=null;}
 if(v==='mancala'){d.pits=Array(14).fill(4);d.pits[6]=d.pits[13]=0;}
 if(v==='dominoes'){const all=labShuffle(Array.from({length:7},(_,a)=>Array.from({length:7-a},(_,b)=>[a,a+b])).flat(),r);d.hands=[all.slice(0,7),all.slice(7,14)];d.pile=all.slice(14);d.chain=[];d.pass=0;}
 if(v==='chess'){d.fen=new LabChess().fen();}
 if(v==='honeycomb'){d.fields=[Array(24).fill(0),Array(24).fill(0)];d.piece=[1,2,3,6][seed%4];d.seed=seed;}
 return d;
 },
 render(d,c){const v=c.variant,turn='<div class="lab-turn" style="--side:'+LAB_COLORS[d.turn]+'">'+esc(labPlayer(d.turn))+' to move</div>';
 if(v==='chess'){const chess=labChess(d),board=chess.board().flat(),glyph={wp:'♙',wn:'♘',wb:'♗',wr:'♖',wq:'♕',wk:'♔',bp:'♟',bn:'♞',bb:'♝',br:'♜',bq:'♛',bk:'♚'},legal=d.selected===null?[]:chess.moves({square:'abcdefgh'[d.selected%8]+(8-Math.floor(d.selected/8)),verbose:true}).map(m=>m.to);return turn+(chess.isCheck()?'<p>Check — protect your king.</p>':'<p>Tap a piece, then a highlighted destination.</p>')+'<div class="lab-checkerboard">'+labGrid(board,8,(p,i)=>'<span class="'+(legal.includes('abcdefgh'[i%8]+(8-Math.floor(i/8)))?'lab-legal':'')+'">'+(p?glyph[p.color+p.type]:'')+'</span>')+'</div>'+(d.promotion?'<p>Choose your promotion</p>'+labOptions('promote',['Queen','Rook','Bishop','Knight']):'')+labButton('resign','Resign game');}
 if(v==='checkers'||v==='kids'){const legal=d.selected===null?[]:labCheckerMoves(d,d.forced).filter(m=>m.from===d.selected).map(m=>m.to);return turn+'<p>Diagonal moves. Captures are compulsory; finish every jump. Kings move both ways.</p><div class="lab-checkerboard">'+labGrid(d.board,d.w,(p,i)=>'<span style="background:'+((i%d.w+Math.floor(i/d.w))%2?'#c4b5dd':'#ebe4ff')+'" class="'+(legal.includes(i)?'lab-legal':'')+'">'+(p?'<b style="color:'+LAB_COLORS[p.owner]+'">'+(p.king?'♛':'●')+'</b>':'')+'</span>')+'</div>'+labButton('resign','Resign game');}
 if(v==='mancala')return turn+'<p>Sow counterclockwise, skip the other store. End in your store for another turn; capture opposite an empty own pit.</p><div class="lab-mancala"><b>'+d.pits[13]+'</b><div><div>'+[12,11,10,9,8,7].map(i=>labButton('pit',d.pits[i],i,d.turn!==1)).join('')+'</div><div>'+[0,1,2,3,4,5].map(i=>labButton('pit',d.pits[i],i,d.turn!==0)).join('')+'</div></div><b>'+d.pits[6]+'</b></div>';
 if(v==='dominoes')return turn+'<div class="lab-callout">Score '+d.score[0]+' : '+d.score[1]+'</div><div class="lab-domino-chain">'+(d.chain.map(t=>'<span>'+t[0]+' │ '+t[1]+'</span>').join('')||'Place any domino to start')+'</div><p>Match an open end. Open-end totals divisible by 5 score that total.</p>'+labOptions('side',['Left end','Right end'])+'<p>Playing on the '+(d.side?'right':'left')+'</p><div class="lab-options">'+d.hands[d.turn].map((t,i)=>labButton('domino',t.join(' │ '),i)).join('')+'</div>'+labButton('draw','Draw / pass')+'<p>'+d.pile.length+' dominoes in the boneyard.</p>';
 if(v==='honeycomb')return turn+'<p>Place a '+d.piece+'-triangle piece in your honeycomb. Pick its first triangle; it wraps around that hexagon.</p><div class="lab-honeycombs">'+d.fields.map((field,k)=>'<section><h3>'+esc(labPlayer(k))+'</h3><div class="lab-hexes">'+[0,1,2,3].map(h=>'<div class="lab-hex">'+Array.from({length:6},(_,j)=>labButton('honey',field[h*6+j]?'▲':'△',k*24+h*6+j,d.turn!==k||!!field[h*6+j])).join('')+'</div>').join('')+'</div></section>').join('')+'</div>'+labButton('passpiece','Cannot fit — exchange piece');
 return turn+'<p>'+esc(v==='tic'?'Make '+d.need+' in a row.':v==='fourrow'?'Drop counters to make four in a row.':'Make the four corners of any square, including tilted squares.')+'</p>'+labGrid(d.board,d.w,v=>v<0?'·':'<b style="color:'+LAB_COLORS[v]+'">'+(v===0?'●':'◆')+'</b>');
 },
 action(d,a,n,c){const v=c.variant;if(a==='resign'){labClassicResult(d,labPlayer(1-d.turn)+' wins by resignation.');return;}
 if(v==='chess'&&(a==='cell'||a==='promote')){const chess=labChess(d);if(a==='promote'&&d.promotion){const p=['q','r','b','n'][n];if(!p)return;const move=chess.move({...d.promotion,promotion:p});d.history.push(move.san);d.promotion=null;d.selected=null;}else if(a==='cell'&&!d.promotion&&n>=0&&n<64){const to='abcdefgh'[n%8]+(8-Math.floor(n/8)),piece=chess.get(to);if(piece?.color===chess.turn()){d.selected=n;return;}if(d.selected===null)return;const from='abcdefgh'[d.selected%8]+(8-Math.floor(d.selected/8)),possible=chess.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!possible.length){game.session.message='Choose a legal highlighted move.';return;}if(possible[0].promotion){d.promotion={from,to};return;}const move=chess.move({from,to});d.history.push(move.san);d.selected=null;}d.fen=chess.fen();d.turn=chess.turn()==='w'?0:1;game.session.moves++;if(chess.isCheckmate())labClassicResult(d,labPlayer(1-d.turn)+' wins by checkmate.');else if(chess.isDraw())labClassicResult(d,'Draw — well played by both sides.');return;}
 if((v==='checkers'||v==='kids')&&a==='cell'&&n>=0&&n<d.board.length){if(d.board[n]?.owner===d.turn){if(d.forced===null||d.forced===n)d.selected=n;return;}const move=labCheckerMoves(d,d.forced).find(m=>m.from===d.selected&&m.to===n);if(!move){game.session.message='Choose a legal move; a jump takes priority.';return;}const p=d.board[move.from];d.board[n]=p;d.board[move.from]=null;if(move.capture!==null)d.board[move.capture]=null;const promoted=!p.king&&(p.owner===0?Math.floor(n/d.w)===0:Math.floor(n/d.w)===d.w-1);if(promoted)p.king=true;game.session.moves++;d.quiet=move.capture!==null||promoted?0:d.quiet+1;if(move.capture!==null&&!promoted&&labCheckerMoves(d,n,true).length){d.forced=n;d.selected=n;return;}d.turn=1-d.turn;d.selected=null;d.forced=null;if(!labCheckerMoves(d).length)labClassicResult(d,labPlayer(1-d.turn)+' wins — no legal reply.');else if(d.quiet>=80)labClassicResult(d,'Draw after 40 moves each without a capture.');return;}
 if(v==='mancala'&&a==='pit'){const own=d.turn===0?n>=0&&n<=5:n>=7&&n<=12;if(!own||!d.pits[n])return;let stones=d.pits[n],i=n;d.pits[n]=0;while(stones){i=(i+1)%14;if(i===(d.turn===0?13:6))continue;d.pits[i]++;stones--;}const store=d.turn===0?6:13;if((d.turn===0?i<6:i>6&&i<13)&&d.pits[i]===1&&d.pits[12-i]>0){d.pits[store]+=d.pits[12-i]+1;d.pits[12-i]=d.pits[i]=0;}game.session.moves++;if(d.pits.slice(0,6).every(n=>n===0)||d.pits.slice(7,13).every(n=>n===0)){d.pits[6]+=d.pits.slice(0,6).reduce((a,b)=>a+b,0);d.pits[13]+=d.pits.slice(7,13).reduce((a,b)=>a+b,0);for(const j of [0,1,2,3,4,5,7,8,9,10,11,12])d.pits[j]=0;labClassicResult(d,d.pits[6]===d.pits[13]?'A tied harvest!':labPlayer(d.pits[6]>d.pits[13]?0:1)+' wins '+d.pits[6]+' to '+d.pits[13]+'.');}else if(i!==store)d.turn=1-d.turn;return;}
 if(v==='dominoes'){if(a==='side'){d.side=n;return;}if(a==='draw'){if(d.pile.length)d.hands[d.turn].push(d.pile.pop());else{const ends=d.chain.length?[d.chain[0][0],d.chain.at(-1)[1]]:[];if(d.hands[d.turn].some(t=>!ends.length||t.some(v=>ends.includes(v)))){game.session.message='You have a playable domino.';return;}d.pass++;if(d.pass===2){const sums=d.hands.map(h=>h.flat().reduce((a,b)=>a+b,0));labClassicResult(d,sums[0]===sums[1]?'Blocked game — tied.':labPlayer(sums[0]<sums[1]?0:1)+' wins with fewer pips.');}else d.turn=1-d.turn;}return;}if(a!=='domino'||!d.hands[d.turn][n])return;let tile=[...d.hands[d.turn][n]];if(d.chain.length){const end=d.side?d.chain.at(-1)[1]:d.chain[0][0];if(!tile.includes(end)){game.session.message='That domino does not fit this end.';return;}if(d.side?tile[0]!==end:tile[1]!==end)tile.reverse();}d.hands[d.turn].splice(n,1);d.side?d.chain.push(tile):d.chain.unshift(tile);const l=d.chain[0],r=d.chain.at(-1),total=d.chain.length===1?l[0]+l[1]:(l[0]===l[1]?l[0]*2:l[0])+(r[0]===r[1]?r[1]*2:r[1]);if(total&&total%5===0)d.score[d.turn]+=total;game.session.moves++;d.pass=0;if(!d.hands[d.turn].length)labClassicResult(d,labPlayer(d.turn)+' emptied their hand! Scores: '+d.score.join(' : '));else d.turn=1-d.turn;return;}
 if(v==='honeycomb'){if(a==='passpiece'){const field=d.fields[d.turn];if(field.some((_,i)=>Array.from({length:d.piece},(_,j)=>Math.floor(i/6)*6+(i%6+j)%6).every(k=>!field[k]))){game.session.message='There is still a place for this piece.';return;}d.piece=1;d.turn=1-d.turn;return;}if(a!=='honey'||Math.floor(n/24)!==d.turn)return;const i=n%24,field=d.fields[d.turn],cells=Array.from({length:d.piece},(_,j)=>Math.floor(i/6)*6+(i%6+j)%6);if(cells.some(k=>field[k]))return;cells.forEach(k=>field[k]=1);game.session.moves++;if(field.every(Boolean))labClassicResult(d);else{d.turn=1-d.turn;d.seed++;d.piece=[1,2,3,6][Math.floor(labRand(d.seed*7919)()*4)];}return;}
 if(a==='cell'&&n>=0&&n<d.board.length){let at=n;if(v==='fourrow'){const col=n%d.w;at=-1;for(let y=d.h-1;y>=0;y--)if(d.board[y*d.w+col]<0){at=y*d.w+col;break;}if(at<0)return;}if(d.board[at]>=0)return;d.board[at]=d.turn;game.session.moves++;let won=false;if(v==='corners'){const cells=d.board.map((v,i)=>v===d.turn?i:-1).filter(i=>i>=0);for(const a of cells)for(const b of cells){const ax=a%d.w,ay=Math.floor(a/d.w),bx=b%d.w,by=Math.floor(b/d.w),dx=bx-ax,dy=by-ay;if(!dx&&!dy)continue;const corners=[[ax-dy,ay+dx],[bx-dy,by+dx]];if(corners.every(([x,y])=>x>=0&&x<d.w&&y>=0&&y<d.h&&d.board[y*d.w+x]===d.turn))won=true;}}else won=labLineWinner(d,d.need)>=0;if(won)labClassicResult(d);else if(d.board.every(v=>v>=0))labClassicResult(d,'Draw — the board is full.');else d.turn=1-d.turn;}
 }
};
